#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "symtable.h"

// Portable replacement for strdup (not available in strict C11)
static char* str_dup(const char* s)
{
    size_t len = strlen(s) + 1;
    char* copy = malloc(len);
    if (copy == NULL) {
        return NULL;
    }
    return memcpy(copy, s, len);
}

// Hashing function, generated by AI
unsigned long hash_djb2(const char* str)
{
    unsigned long hash = 5381;
    int c;

    while ((c = (unsigned char)*str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash;
}

bool symtable_init(SymTable* t)
{
    t->count = 0;
    t->size = TABLE_SIZE;
    t->entries = calloc(TABLE_SIZE, sizeof(Symbol));
    if (t->entries == NULL) {
        return false;
    }

    if (t->entries == NULL) {
        t->size = 0;
        t->count = 0;
        return false;
    }
    return true;
}

void symtable_free(SymTable* t)
{
    for (size_t i = 0; i < t->size; i++) {
        if (t->entries[i].state == SLOT_OCCUPIED) {
            free(t->entries[i].key);
            if (t->entries[i].type == SYM_FUNC) {
                free(t->entries[i].func.param_types);
            }
        }
    }
    free(t->entries);
    t->entries = NULL;
    t->size = 0;
    t->count = 0;
}

static bool symtable_resize(SymTable* t, size_t new_size)
{
    if (new_size <= t->count) {
        return false;
    }

    Symbol* new_entries = calloc(new_size, sizeof(Symbol));
    if (new_entries == NULL) {
        return false;
    }

    for (size_t i = 0; i < t->size; i++) {
        if (t->entries[i].state != SLOT_OCCUPIED) {
            continue;
        }

        size_t idx = hash_djb2(t->entries[i].key) % new_size;
        while (new_entries[idx].state == SLOT_OCCUPIED) {
            idx = (idx + 1) % new_size;
        }

        new_entries[idx] = t->entries[i];
    }

    free(t->entries);
    t->entries = new_entries;
    t->size = new_size;
    return true;
}

int symtable_insert(SymTable* t, const char* key)
{
    if (symtable_lookup(t, key)) {
        return RET_DUPLICATE;
    }

    if ((t->count + 1) * 10 > t->size * 6) {
        bool resized = symtable_resize(t, t->size * 2);
        if (!resized) {
            return RET_ERR;
        }
    }

    unsigned long idx = hash_djb2(key) % t->size;

    size_t steps = 0; // there should always be a free space, so steps should never reach max amount
    while (steps != t->size) {
        if (t->entries[idx].state == SLOT_EMPTY) {
            memset(&t->entries[idx], 0, sizeof(Symbol));

            char* copy = str_dup(key);
            if (copy == NULL) {
                return RET_ERR;
            }
            t->entries[idx].key = copy;
            t->entries[idx].state = SLOT_OCCUPIED;
            t->count++;

            return RET_OK;
        }

        idx = (idx + 1) % t->size;
        steps++;
    }

    return RET_ERR;
}

Symbol* symtable_lookup(const SymTable* t, const char* key)
{
    if (t->size == 0) {
        return NULL;
    }

    unsigned long idx = hash_djb2(key) % t->size;

    size_t steps = 0;
    while (steps != t->size) {
        if (t->entries[idx].state == SLOT_EMPTY) {
            return NULL;
        }

        // slot is occupied
        if (strcmp(key, t->entries[idx].key) == 0) {
            return &t->entries[idx];
        }

        idx = (idx + 1) % t->size;
        steps++;
    }
    return NULL;
}
